<?php namespace App\Filament\Resources;
use App\Models\IndividualStudyPlan;use App\Filament\Resources\IndividualStudyPlanResource\Pages;use App\Services\PeriodGuard;use Illuminate\Support\Facades\DB;use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\Resource;use Filament\Resources\Table;use Filament\Tables;
class IndividualStudyPlanResource extends Resource{protected static ?string $model=IndividualStudyPlan::class;protected static ?string $navigationGroup='Учебная часть';protected static ?string $navigationLabel='Индивидуальные планы';protected static ?string $pluralModelLabel='Индивидуальные учебные планы';
public static function form(Form $f):Form{return $f->schema([Forms\Components\Select::make('student_id')->label('Студент')->options(fn()=>DB::table('students')->where('status','active')->orderBy('last_name')->get()->mapWithKeys(fn($s)=>[$s->id=>trim($s->last_name.' '.$s->first_name.' '.$s->middle_name)]))->searchable()->required(),Forms\Components\Select::make('subject_id')->label('Дисциплина')->options(fn()=>DB::table('subjects')->orderBy('name')->pluck('name','id'))->searchable()->required(),Forms\Components\TextInput::make('planned_hours')->label('Часы')->numeric()->minValue(0),Forms\Components\Select::make('control_type')->label('Форма контроля')->options(['exam'=>'Экзамен','credit'=>'Зачёт','differentiated_credit'=>'Дифференцированный зачёт','coursework'=>'Курсовая работа','other'=>'Другое']),Forms\Components\Textarea::make('note')->label('Примечание')->columnSpan('full')])->columns(2);}
public static function table(Table $t):Table{return $t->columns([Tables\Columns\TextColumn::make('student_id')->label('Студент')->formatStateUsing(fn($id)=>($s=DB::table('students')->find($id))?trim($s->last_name.' '.$s->first_name):'—')->searchable(),Tables\Columns\TextColumn::make('subject_id')->label('Дисциплина')->formatStateUsing(fn($id)=>DB::table('subjects')->where('id',$id)->value('name')?:'—'),Tables\Columns\TextColumn::make('planned_hours')->label('Часы'),Tables\Columns\TextColumn::make('control_type')->label('Контроль'),Tables\Columns\BadgeColumn::make('status')->label('Статус')])->actions([Tables\Actions\EditAction::make()]);}
public static function getEloquentQuery():\Illuminate\Database\Eloquent\Builder{$q=parent::getEloquentQuery();$p=request()->attributes->get('academic_period');return $p?$q->where('academic_period_id',$p->id):$q;}
public static function canViewAny():bool{$u=auth()->user();return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('head_academic')||$u->canDo('students.manage'));}public static function canCreate():bool{return static::canViewAny();}public static function canEdit($record):bool{return static::canViewAny();}public static function canDelete($record):bool{return false;}public static function getPages():array{return['index'=>Pages\ListIndividualStudyPlans::route('/'),'create'=>Pages\CreateIndividualStudyPlan::route('/create'),'edit'=>Pages\EditIndividualStudyPlan::route('/{record}/edit')];}}